exercise.referenceSolution:
#include <stdio.h>
#include <string.h>

typedef struct {
    char text[21];
} Word;

int main(void) {
    int n;
    if (scanf("%d", &n) != 1 || n < 1 || n > 100) {
        return 0;
    }
    Word words[100];
    for (int i = 0; i < n; i++) {
        scanf("%20s", words[i].text);
    }
    for (int i = 1; i < n; i++) {
        Word key = words[i];
        int j = i - 1;
        while (j >= 0 && strcmp(words[j].text, key.text) > 0) {
            words[j + 1] = words[j];
            j--;
        }
        words[j + 1] = key;
    }
    for (int i = 0; i < n; i++) {
        printf(i + 1 < n ? "%s " : "%s\n", words[i].text);
    }
    return 0;
}

additionalExercises.description:
Посчитаем, сколько работы делает сортировка вставками на разных входах.

Первая строка — `n`, вторая — `n` целых чисел (при `n = 0` строка пустая). Отсортируйте их по неубыванию так:

```c
for (i = 1; i < n; i++) {
    key = values[i];
    j = i - 1;
    while (j >= 0 && values[j] > key) {   // сравнение — вычисление values[j] > key
        values[j + 1] = values[j];        // сдвиг
        j--;
    }
    values[j + 1] = key;                  // запись ключа — не сдвиг
}
```

Напечатайте три строки: `сравнений: C`, `сдвигов: S` и отсортированный массив через пробел (пустая строка при `n = 0`). Сравнение не выполняется, когда `j < 0`.

