#include <stdio.h>

int main(void) {
    int n;
    if (scanf("%d", &n) != 1 || n < 0 || n > 1000) {
        return 0;
    }
    int values[1000];
    for (int i = 0; i < n; i++) {
        scanf("%d", &values[i]);
    }
    long long comparisons = 0, shifts = 0;
    for (int i = 1; i < n; i++) {
        int key = values[i];
        int j = i - 1;
        while (j >= 0) {
            comparisons++;
            if (!(values[j] > key)) {
                break;
            }
            values[j + 1] = values[j];
            shifts++;
            j--;
        }
        values[j + 1] = key;
    }
    printf("сравнений: %lld\n", comparisons);
    printf("сдвигов: %lld\n", shifts);
    for (int i = 0; i < n; i++) {
        printf(i + 1 < n ? "%d " : "%d", values[i]);
    }
    printf("\n");
    return 0;
}

